
.hh-summary {
  background: rgba(236, 72, 153, 0.1);
  padding: 8px 12px;
  border-radius: 8px;
  margin-bottom: 12px;
  font-size: 12px;
  color: #be185d;
  font-weight: 600;
}

.hh-tag-green {
  display: inline-block;
  background: rgba(16, 185, 129, 0.2);
  color: #059669;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 10px;
  margin-left: 8px;
}

.hh-tag-blue {
  display: inline-block;
  background: rgba(59, 130, 246, 0.2);
  color: #2563eb;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 10px;
  margin-left: 8px;
}
