
.edit-actions {
  display: flex;
  gap: 10px;
  margin-bottom: 12px;
}

.edit-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 16px;
  border: 0;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.2s;

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }

  &.save {
    background: linear-gradient(135deg, #ff5fae, #db2777);
    color: white;

    &:hover:not(:disabled) {
      background: linear-gradient(135deg, #ff77b7, #ec4899);
    }
  }

  &.reset {
    background: rgba(236, 72, 153, 0.15);
    color: #be185d;
    border: 1px solid rgba(236, 72, 153, 0.3);

    &:hover:not(:disabled) {
      background: rgba(236, 72, 153, 0.25);
    }
  }
}

.var-tree {
  font-size: 12px;
}

.var-category {
  margin-bottom: 8px;
  background: rgba(255, 255, 255, 0.5);
  border-radius: 12px;
  overflow: hidden;
}

.var-category-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: linear-gradient(135deg, rgba(244, 114, 182, 0.2), rgba(236, 72, 153, 0.15));
  cursor: pointer;
  font-weight: 800;
  color: #831843;
  transition: background 0.2s;

  &:hover {
    background: linear-gradient(135deg, rgba(244, 114, 182, 0.35), rgba(236, 72, 153, 0.25));
  }

  i {
    font-size: 10px;
    width: 12px;
  }
}

.var-category-name {
  flex: 1;
}

.var-category-count {
  background: rgba(236, 72, 153, 0.3);
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 10px;
}

.var-category-content {
  padding: 8px;
}
