
.var-row-wrapper {
  width: 100%;
}

.var-row {
  display: flex;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 8px;
  align-items: center;

  &:hover {
    background: rgba(244, 114, 182, 0.1);
  }

  &.var-row-complex {
    background: rgba(244, 114, 182, 0.05);
  }
}

.var-key {
  min-width: 80px;
  display: flex;
  align-items: center;
  gap: 4px;
  color: #be185d;
  font-weight: 700;
  cursor: pointer;

  i {
    font-size: 8px;
    width: 12px;
    color: #9f647f;
  }

  &:hover {
    color: #9d174d;
  }
}

.var-value {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  color: #5b173c;
  cursor: pointer;

  &:hover {
    color: #831843;
  }
}

.var-modified {
  color: #059669;
  font-weight: 700;
  background: rgba(5, 150, 105, 0.1);
  padding: 2px 6px;
  border-radius: 4px;
}

.var-modified-tag {
  width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(239, 68, 68, 0.2);
  color: #dc2626;
  border-radius: 50%;
  font-size: 10px;
  cursor: pointer;

  &:hover {
    background: rgba(239, 68, 68, 0.4);
  }
}

.var-complex {
  color: #9f647f;
  font-style: italic;
  display: flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;

  i {
    font-size: 8px;
    color: #831843;
  }
}

.var-input {
  flex: 1;
  min-width: 60px;
  border: 1px solid rgba(236, 72, 153, 0.4);
  background: rgba(255, 255, 255, 0.9);
  border-radius: 6px;
  padding: 4px 8px;
  font-size: 12px;
  color: #831843;
  outline: none;

  &:focus {
    border-color: #ec4899;
    box-shadow: 0 0 0 2px rgba(236, 72, 153, 0.2);
  }
}

.var-num-btn {
  width: 24px;
  height: 24px;
  border: 0;
  border-radius: 6px;
  background: linear-gradient(135deg, #f472b6, #ec4899);
  color: white;
  font-weight: 900;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;

  &:hover {
    background: linear-gradient(135deg, #ec4899, #db2777);
  }

  &:active {
    transform: scale(0.95);
  }
}

.var-add-btn, .var-remove-btn {
  width: 20px;
  height: 20px;
  border: 0;
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
}

.var-add-btn {
  background: rgba(16, 185, 129, 0.2);
  color: #059669;

  &:hover {
    background: rgba(16, 185, 129, 0.4);
  }
}

.var-remove-btn {
  background: rgba(239, 68, 68, 0.2);
  color: #dc2626;

  &:hover {
    background: rgba(239, 68, 68, 0.4);
  }
}

.var-children {
  margin-left: 20px;
  padding-left: 12px;
  border-left: 2px solid rgba(236, 72, 153, 0.2);
}

.var-array-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 4px 8px;
  margin: 4px 0;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 6px;

  .var-input {
    flex: 1;
  }
}

.var-array-item-header {
  display: flex;
  align-items: center;
  gap: 8px;
}

.var-array-index {
  min-width: 20px;
  font-size: 10px;
  color: #9f647f;
  font-weight: 600;
}

.var-array-item-children {
  margin-left: 24px;
  padding-left: 12px;
  border-left: 2px solid rgba(236, 72, 153, 0.2);
}

.var-child-row {
  margin: 4px 0;
}
